def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    candidates = [v for v in counts if v not in (background, 2)]
    if not candidates:
        return [row[:] for row in grid]
    marker = max(candidates, key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not points:
        return [row[:] for row in grid]
    rmin = min(r for r, c in points); rmax = max(r for r, c in points)
    cmin = min(c for r, c in points); all_cmax = max(c for r, c in points)
    col_rows = {}
    for r, c in points: col_rows.setdefault(c, []).append(r)
    strong_cols = [c for c, rows in col_rows.items() if len(rows) >= 4]
    strong_right = max(strong_cols) if strong_cols else all_cmax
    out = [row[:] for row in grid]

    # If sparse outlying marks lie beyond the repeated frame, bridge only the
    # repeated lines, rather than drawing a spurious outer frame around them.
    if all_cmax > strong_right:
        for r in range(h):
            cols = sorted(c for rr, c in points if rr == r)
            if len(cols) >= 4:
                for c in range(min(cols), max(cols) + 1):
                    if out[r][c] == background: out[r][c] = 2
            elif len(cols) >= 3:
                for a, b in zip(cols, cols[1:]):
                    if b-a == 2 and out[r][a+1] == background: out[r][a+1] = 2
        for c, rows0 in col_rows.items():
            rows = sorted(rows0)
            if len(rows) >= 4:
                for r in range(min(rows), max(rows)+1):
                    if out[r][c] == background: out[r][c] = 2
            elif len(rows) >= 3:
                for a, b in zip(rows, rows[1:]):
                    if b-a == 2 and out[a+1][c] == background: out[a+1][c] = 2
        return out

    # Otherwise complete the perimeter and bridge one-cell gaps on repeated lines.
    for c in range(cmin, all_cmax + 1):
        if out[rmin][c] == background: out[rmin][c] = 2
        if out[rmax][c] == background: out[rmax][c] = 2
    for r in range(rmin, rmax + 1):
        if out[r][cmin] == background: out[r][cmin] = 2
        if out[r][all_cmax] == background: out[r][all_cmax] = 2
    for r in range(h):
        cols = sorted(c for rr, c in points if rr == r)
        if len(cols) >= 3:
            for a,b in zip(cols,cols[1:]):
                if b-a==2 and out[r][a+1]==background: out[r][a+1]=2
    for c, rows0 in col_rows.items():
        rows=sorted(rows0)
        if len(rows)>=3:
            for a,b in zip(rows,rows[1:]):
                if b-a==2 and out[a+1][c]==background: out[a+1][c]=2
    for r in range(h):
        cols=sorted(c for rr,c in points if rr==r)
        if any(b==a+1 for a,b in zip(cols,cols[1:])):
            for c in range(cmin,all_cmax+1):
                if out[r][c]==background: out[r][c]=2
    for c in range(cmin,all_cmax+1):
        rows=sorted(r for r,cc in points if cc==c)
        if any(b==a+1 for a,b in zip(rows,rows[1:])):
            for r in range(rmin,rmax+1):
                if out[r][c]==background: out[r][c]=2
    return out
